<template><div class="login-page"><div class="login-card"><h2>{{ isForgot ? t('forgotPassword') : isRegister ? t('registerTitle') : t('loginTitle') }}</h2><form class="login-form" @submit.prevent="submit"><div v-if="!isForgot" class="login-field"><label>{{ t('usernameLabel') }}</label><input v-model="username" type="text" :placeholder="t('usernamePlaceholder')" required /></div><div v-if="isRegister || isForgot" class="login-field"><label>{{ t('emailLabel') }}</label><input v-model="email" type="email" :placeholder="isRegister ? t('registerEmailPlaceholder') : t('emailPlaceholder')" :required="isForgot" /></div><template v-if="isForgot && resetCodeSent"><div class="login-field"><label>{{ t('emailVerificationCode') }}</label><input v-model="resetCode" inputmode="numeric" maxlength="6" :placeholder="t('emailCodePlaceholder')" required /></div><div class="login-field"><label>{{ t('newPassword') }}</label><input v-model="resetPassword" type="password" :placeholder="t('newPasswordPlaceholder')" required /></div><div class="login-field"><label>{{ t('confirmNewPassword') }}</label><input v-model="resetConfirmPassword" type="password" :placeholder="t('confirmPasswordPlaceholder')" required /></div></template><template v-if="isRegister"><div class="login-field"><label>{{ t('nicknameLabel') }}</label><input v-model="nickname" type="text" :placeholder="t('nicknamePlaceholder')" /></div><div class="login-field"><label>{{ t('chooseAvatar') }}</label><div class="avatar-options"><div v-for="item in avatars" :key="item" :class="['avatar-option', { selected: avatar === item }]" @click="avatar = item"><AvatarIcon :type="item" :is-animating="avatar === item" :size="item === 'eye' ? 30 : 40" /></div></div></div></template><div v-if="!isForgot" class="login-field"><label>{{ t('passwordLabel') }}</label><input v-model="password" type="password" :placeholder="t('passwordPlaceholder')" required /></div><div v-if="error" class="login-error">{{ error }}</div><a v-if="showAppeal" class="login-appeal-link" href="https://t.me/CyrusOliver" target="_blank" rel="noreferrer">账号申诉</a><div v-if="message" class="login-success">{{ message }}</div><button class="login-submit" type="submit" :disabled="loading">{{ loading ? t('processing') : isForgot ? (resetCodeSent ? t('confirmReset') : t('sendResetCode')) : isRegister ? t('register') : t('loginBtn') }}</button></form><div class="login-switch">{{ isForgot ? t('rememberPassword') : isRegister ? t('haveAccount') : t('noAccount') }}<button @click="switchMode(isRegister || isForgot ? 'login' : 'register')">{{ isRegister || isForgot ? t('goLogin') : t('goRegister') }}</button></div><div v-if="!isRegister && !isForgot" class="login-switch"><button @click="switchMode('forgot')">{{ t('forgotPassword') }}</button></div></div></div></template>
<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuth, useLang } from '../contexts/app'
import { authService } from '../services/authService'
import AvatarIcon from '../components/AvatarIcon.vue'
import './LoginPage.css'
const router=useRouter();const {login}=useAuth();const {t}=useLang();const mode=ref('login'),username=ref(''),password=ref(''),nickname=ref(''),email=ref(''),resetCode=ref(''),resetPassword=ref(''),resetConfirmPassword=ref(''),resetCodeSent=ref(false),avatar=ref('eye'),error=ref(''),message=ref(''),showAppeal=ref(false),loading=ref(false);const avatars=['eye','ear','nose','mouth'];const isRegister=computed(()=>mode.value==='register'),isForgot=computed(()=>mode.value==='forgot');const switchMode=(next)=>{mode.value=next;error.value='';message.value='';showAppeal.value=false;resetCode.value='';resetPassword.value='';resetConfirmPassword.value='';resetCodeSent.value=false};const submit=async()=>{error.value='';message.value='';showAppeal.value=false;loading.value=true;try{if(isForgot.value){if(!resetCodeSent.value){const data=await authService.forgotPassword(email.value);resetCodeSent.value=true;message.value=data.detail||t('resetCodeSent')}else{if(resetPassword.value.length<4){error.value=t('passwordMinLength');return}if(resetPassword.value!==resetConfirmPassword.value){error.value=t('passwordMismatch');return}const data=await authService.resetPassword(email.value,resetCode.value,resetPassword.value);message.value=data.detail||t('passwordResetSuccess');resetCode.value='';resetPassword.value='';resetConfirmPassword.value=''}}else{const data=isRegister.value?await authService.register(username.value,password.value,nickname.value||username.value,avatar.value,email.value):await authService.login(username.value,password.value);login(data.user,data.token);router.push('/')}}catch(e){showAppeal.value=!isForgot.value&&!isRegister.value&&e.response?.status===403;error.value=e.response?.data?.detail||t('loginFailed')}finally{loading.value=false}}</script>
<style scoped>.avatar-options{display:flex;gap:15px;justify-content:center;margin-top:10px;align-items:center}.avatar-option{width:50px;height:50px;border:2px solid transparent;border-radius:8px;padding:2px;cursor:pointer;display:flex;align-items:center;justify-content:center;overflow:visible}.avatar-option.selected{border-color:red}</style>
